SourceCode.Declaration:
/// <summary>
/// Data contract for CPI-driven Sales Order repricing.
/// Provides parameters required for batch execution such as site selection,
/// thread count, process identifiers, and query definitions.
/// </summary>
[
    DataContract,
    SysOperationAlwaysInitialize,
    SysOperationContractProcessing(classStr(METCPIRepricingUIBuilder))
    ]
    class METCPIRepricingContract extends METSysOperationTaskDataContract implements SysOperationInitializable
{
    guid    topPickingProcessId;
    str     packedQuery;
    List    inventSiteIdList;

}

Method.Source:
/// <summary>
/// Initializes the contract.
/// </summary>
public void initialize()
{
    super();

    inventSiteIdList = new List(Types::String);
}

/// <summary>
/// Gets or sets the list of inventory site IDs.
/// </summary>
/// <param name="_inventSiteIdList">
/// Optional site ID list to assign.
/// </param>
/// <returns>
/// The current site ID list.
/// </returns>
[
    DataMember,
    DataCollection(Types::String),
    SysOperationLabel("@SYS103211"),
    SysOperationDisplayOrder('3'),
    AifCollectionType('return', Types::String)
]
public List parmInventSiteIdList(List _inventSiteIdList = inventSiteIdList)
{
    inventSiteIdList = _inventSiteIdList;
    return inventSiteIdList;
}

/// <summary>
/// Gets or sets the number of threads used during batch execution.
/// </summary>
/// <param name="_threadCount">Thread count.</param>
/// <returns>The configured thread count.</returns>
[
    DataMember,
    SysOperationDisplayOrder('1'),
    SysOperationControlVisibilityAttribute(true)
]
public METThreadCount parmThreadCount(METThreadCount _threadCount = threadCount)
{
    threadCount = _threadCount;
    return threadCount;
}

/// <summary>
/// Gets or sets the process identifier.
/// </summary>
/// <param name="_topPickingProcessId">Process GUID.</param>
/// <returns>The current process identifier.</returns>
[
    DataMember,
    SysOperationDisplayOrder('2'),
    SysOperationControlVisibility(false)
]
public guid parmTopPickingProcessId(guid _topPickingProcessId = topPickingProcessId)
{
    topPickingProcessId = _topPickingProcessId;
    return topPickingProcessId;
}

/// <summary>
/// Gets or sets the packed query string.
/// </summary>
/// <param name="_packedQuery">Base64 encoded query.</param>
/// <returns>The packed query string.</returns>
[
    DataMemberAttribute,
    AifQueryTypeAttribute('_packedQuery', queryStr(METCPIRepricingQuery))
]
public str parmPackedQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;
    return packedQuery;
}

/// <summary>
/// Returns the unpacked query.
/// </summary>
/// <returns>The decoded query object.</returns>
public Query getQuery()
{
    return new Query(SysOperationHelper::base64Decode(packedQuery));
}

/// <summary>
/// Initializes the query and applies site filters.
/// </summary>
/// <returns>
/// Query object with InventSiteId filtering applied.
/// </returns>
public Query initQuery()
{
    Query                query;
    QueryBuildDataSource qbds;
    ListEnumerator       enumerator;
    container            siteIds;

    query = this.getQuery();
    qbds  = query.dataSourceTable(tableNum(SalesTable));

    if (qbds && inventSiteIdList && inventSiteIdList.elements())
    {
        enumerator = inventSiteIdList.getEnumerator();

        while (enumerator.moveNext())
        {
            siteIds += [enumerator.current()];
        }

        qbds.addRange(fieldNum(SalesTable, InventSiteId))
        .value(SysQuery::value(siteIds));
    }

    return query;
}

/// <summary>
/// Validates contract parameters.
/// </summary>
/// <returns>
/// True if validation succeeds; otherwise false.
/// </returns>
public boolean validate()
{
    boolean isValid = super();

    if (!inventSiteIdList || !inventSiteIdList.elements())
    {
        isValid = checkFailed("@MET:SiteMandatory") && isValid;
    }

    return isValid;
}
